<script setup lang="ts">
import {USE_ILLUSTRATED_ART} from '../presentation';
import NpcAvatar from './NpcAvatar.vue';
defineProps<{rooms:any[],selected:string|null,visitors:any[],buildingName?:string}>();defineEmits<{select:[id:string],visit:[propertyId:string]}>();
const status=(room:any)=>!room.owned?'待售':room.renovatingMonths?'施工中':room.condition<40?'待维修':room.renewalCount?'待续租':!room.vacancies?'满住':room.askingRent===null?'未挂牌':room.applicantCount?'谈价中':'待租';
const positions:Record<string,{left:string,top:string}>={'xingfu-402':{left:'40%',top:'30%'},'xingfu-403':{left:'67%',top:'30%'},'xingfu-301':{left:'40%',top:'47%'},'university-101':{left:'40%',top:'30%'},'tech-302':{left:'40%',top:'30%'}};
</script>
<template><div class="scene"><div class="building-canvas"><svg v-if="!USE_ILLUSTRATED_ART" class="street-art simple-building" viewBox="0 0 400 600" aria-hidden="true"><rect width="400" height="600" fill="#b9cdc3"/><path d="M0 540Q190 470 400 540V600H0Z" fill="#98a685"/><path d="M46 66L346 66 367 90H25Z" fill="#986c4c"/><text x="196" y="83" text-anchor="middle" fill="#f9eacc" font-size="14">{{buildingName??(rooms[0]?.regionId==="university"?"大学城":rooms[0]?.regionId==="tech"?"科技园":"幸福里")}}</text><rect x="40" y="90" width="312" height="411" fill="#d9ba86"/><rect x="52" y="90" width="288" height="411" fill="#efdbaf"/><g fill="#8a7052"><rect x="113" y="105" width="77" height="54" rx="4"/><rect x="221" y="105" width="77" height="54" rx="4"/><rect x="113" y="201" width="77" height="54" rx="4"/><rect x="221" y="201" width="77" height="54" rx="4"/><rect x="113" y="313" width="77" height="54" rx="4"/><rect x="221" y="313" width="77" height="54" rx="4"/></g><g fill="#b3ccd0"><rect x="121" y="111" width="61" height="40"/><rect x="229" y="111" width="61" height="40"/><rect x="121" y="207" width="61" height="40"/><rect x="229" y="207" width="61" height="40"/><rect x="121" y="319" width="61" height="40"/><rect x="229" y="319" width="61" height="40"/></g><rect x="143" y="410" width="99" height="90" fill="#857453"/><rect x="151" y="419" width="38" height="77" fill="#91aaa3"/><rect x="196" y="419" width="38" height="77" fill="#91aaa3"/><rect x="32" y="498" width="328" height="14" fill="#aa8c64"/></svg><img v-else class="street-art" src="/assets/neighborhood.webp" alt="幸福里的老街出租楼，窗灯与楼下的小商铺"><div v-if="!USE_ILLUSTRATED_ART" class="window-life"><div v-for="room in rooms" :key="room.id" class="room-life" :style="{left:room.id==='xingfu-403'?'64.875%':'37.875%',top:room.id==='xingfu-301'?'37.833%':'21.833%'}" :class="{owned:room.owned,construction:room.renovatingMonths}"><div v-if="room.tenantIds.length" class="window-households"><NpcAvatar v-for="id in room.tenantIds" :key="id" :tenant-id="id" compact/></div><template v-else-if="room.renovatingMonths"><i class="material-stack"></i><NpcAvatar tenant-id="worker" compact/></template><template v-else><i class="window-bed"></i><i class="window-table"></i></template></div></div><button v-for="room in rooms" :key="room.id" class="door-sign" :aria-label="`${room.name}，${!room.owned?'待售':room.renovatingMonths?'装修中':room.occupancy?`${room.occupancy}/3户`:'0/3户'}，查看房间`" :aria-pressed="selected===room.id" :style="positions[room.id]" @click="$emit('select',room.id)"><b class="full-room-name">{{room.name}}</b><b class="room-number">{{room.name.match(/\d+/)?.[0]}}</b><span>{{status(room)}}{{room.owned?' · '+room.occupancy+'/3户':''}}</span></button><div class="street-visitors"><button v-for="v in visitors" :key="v.id" @click="$emit('visit',v.propertyId)"><NpcAvatar :tenant-id="v.tenantId"/><span>{{v.name}}来访</span></button></div></div></div></template>
